if PUBLIC_MODE:
    SECURITY_HEADERS["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"

_hits: dict[tuple[str, str], deque] = {}


def _client_ip(request: Request) -> str:
    """Real client IP behind Render's proxy: the right-most X-Forwarded-For entry is added by the proxy
    itself, so it cannot be spoofed by the client (left-most entries can)."""
    forwarded = request.headers.get("x-forwarded-for", "")
    if forwarded:
        return forwarded.split(",")[-1].strip()
    return request.client.host if request.client else "unknown"


def _rate_limited(request: Request) -> bool:
    """Sliding one-minute window per client IP and endpoint (public mode only)."""
    limit = RATE_LIMITS.get(request.url.path)
    if not PUBLIC_MODE or not limit or request.method != "POST":
        return False
    now = time.monotonic()
    key = (_client_ip(request), request.url.path)
    window = _hits.setdefault(key, deque())
    while window and now - window[0] > 60:
        window.popleft()
    if len(window) >= limit:
        return True
    window.append(now)
    if len(_hits) > 20_000:  # bound memory: drop idle clients
        for k in [k for k, v in _hits.items() if not v or now - v[-1] > 60]:
            _hits.pop(k, None)
    return False


@app.middleware("http")
async def security_headers(request: Request, call_next):
    """Rate-limit expensive endpoints, attach security headers; API responses are never cached."""
    if _rate_limited(request):
        response = JSONResponse(status_code=429, content={"detail": "err_rate_limited"},
                                headers={"Retry-After": "60"})
    else:
        response = await call_next(request)
    response.headers.update(SECURITY_HEADERS)
    if request.url.path.startswith("/api/"):
        response.headers["Cache-Control"] = "no-store"
    return response


class AnalyzeIn(BaseModel):
    resume_text: str = Field(..., min_length=30, max_length=MAX_TEXT_CHARS)
    job_description: str = Field("", max_length=MAX_TEXT_CHARS)
    file_meta: dict | None = None


class OptimizeIn(BaseModel):
    resume_text: str = Field(..., min_length=30, max_length=MAX_TEXT_CHARS)
    job_description: str = Field("", max_length=MAX_TEXT_CHARS)
    language: Lang | None = None


class CoverLetterIn(OptimizeIn):
    company: str = Field("", max_length=120)
    role: str = Field("", max_length=120)


class TranslateIn(BaseModel):
    text: str = Field(..., min_length=10, max_length=MAX_TEXT_CHARS)
    target_language: Lang


class PreviewIn(BaseModel):
    resume_text: str = Field(..., min_length=30, max_length=MAX_TEXT_CHARS)
    template: Template = "modern"
    accent: Accent | None = None
    bold_keywords: bool = False
    job_description: str = Field("", max_length=MAX_TEXT_CHARS)
    language: Lang | None = None


class ExportIn(PreviewIn):
    format: Literal["pdf", "docx"] = "pdf"


def _safe_meta(meta: dict | None) -> dict:
    """Only keep known numeric/boolean file metadata coming back from the client."""
    meta = meta or {}
    out = {k: meta[k] for k in ("pages", "images", "tables") if isinstance(meta.get(k), int) and 0 <= meta[k] < 10_000}
    out["header_footer_text"] = meta.get("header_footer_text") is True
    return out


