@app.post("/api/preview")
async def preview(body: PreviewIn):
    """HTML of the resume in the chosen template (rendered in a sandboxed iframe by the UI)."""
    return {"html": render_html(body.resume_text, body.template, body.accent, body.bold_keywords,
                                body.job_description, for_pdf=False, lang=body.language)}


@app.post("/api/extract")
async def extract(file: UploadFile = File(...)):
    """Extract text from an uploaded PDF/DOCX/TXT resume (max 5 MB)."""
    data = await file.read(MAX_UPLOAD_BYTES + 1)
    await file.close()
    try:
        text, meta = extract_text(file.filename or "", data)
    except UploadError as exc:
        raise HTTPException(status_code=400, detail=exc.code) from exc
    return {"text": text, "meta": meta, "language": detect_language(text)}


@app.post("/api/analyze")
async def analyze_route(body: AnalyzeIn):
    """ATS score, keyword match, missing skills, risks and weak points."""
    return analyze(body.resume_text, body.job_description, _safe_meta(body.file_meta))


@app.post("/api/optimize")
async def optimize_route(body: OptimizeIn):
    """Rewrite the resume (local AI, or rule-based fallback)."""
    return await optimizer.optimize(body.resume_text, body.job_description, body.language)


@app.post("/api/cover-letters")
async def cover_letters(body: CoverLetterIn):
    """Formal, conversational and enthusiastic cover letters."""
    return await cover_letter.generate_letters(body.resume_text, body.job_description, body.language,
                                               body.company.strip(), body.role.strip())


@app.post("/api/translate")
async def translate(body: TranslateIn):
    """Translate the resume; requires the local AI model."""
    try:
        return await optimizer.translate(body.text, body.target_language)
    except llm.AIUnavailable as exc:
        raise HTTPException(status_code=503, detail="ai_unavailable") from exc


@app.post("/api/export")
async def export(body: ExportIn):
    """Download the resume as PDF or DOCX in the chosen template."""
    if body.format == "docx":
        data = export_docx(body.resume_text, body.template, body.accent, body.bold_keywords,
                           body.job_description, body.language)
    else:
        html = render_html(body.resume_text, body.template, body.accent, body.bold_keywords,
                           body.job_description, for_pdf=True, lang=body.language)
        try:
            data = await engine.html_to_pdf(html)
        except BrowserUnavailable:
            data = legacy_export(plain(body.resume_text), LEGACY_TEMPLATE.get(body.template, body.template),
                                 "pdf", body.language)
    name = safe_filename(parse_resume(body.resume_text).get("name", ""), body.format)
    media = "application/pdf" if body.format == "pdf" else \
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    return Response(data, media_type=media, headers={"Content-Disposition": f'attachment; filename="{name}"'})


@app.exception_handler(Exception)
async def unhandled(_: Request, exc: Exception):
    """Never leak stack traces to the client."""
    return JSONResponse(status_code=500, content={"detail": "err_server"})


app.mount("/static", StaticFiles(directory=STATIC_DIR), name="static")
